L=open('crates/pony-agent-core/src/bin/tui.rs',encoding='utf-8').read().splitlines()
g=lambda n:L[n-1]
assert 'orphan_dispatch_payload(queue_dispatch_payload.as_deref(), dispatch_pending)' in g(10611)
assert 'state.clear_input();' in g(10614)
assert '保留用户当前输入不动' in g(10311)
print('[anchors] 10611 收割入口 | 10614 无条件清框 | 10311 分歧分支「保留用户当前输入不动」')
class S:
    def __init__(s): s.q=['m1','m2'];s.c='';s.p=None;s.d=None;s.n=0;s.sent=[];s.wiped=[];s.t=[];s.st=False
    lat=lambda s:(s.d is not None and s.n<s.d)
    def gate(s):
        if not s.lat() and s.p and s.p.strip():                 # 10611-10626 孤儿收割
            if s.c.strip() and s.c.strip()!=s.p.strip(): s.wiped.append(s.c)
            s.q.insert(0,s.p.strip()); s.c=''; s.p=None
            print(f'  {s.n}ms ORPHAN-HARVEST requeue=1 清框(丢 {s.wiped[-1]!r}) continue'); return
        if s.c.strip() or s.st or not(s.q and not s.lat()): return
        s.p=s.q.pop(0); s.c=s.p+' '; s.d=s.n+2000; print(f'  {s.n}ms GATE dispatch {s.p!r}')
    def run(s,ev,stall=None):
        s.t=list(ev); done=False
        while s.t:
            k=s.t.pop(0)
            if stall and not done and k==stall: done=True; s.n+=2100; print(f'  {s.n}ms 循环头停顿 +2100ms(NFR<=3000)')
            if k=='SC': print(f'  {s.n}ms StreamCompleted'); s.st=False; s.gate()
            elif k=='QAS': print(f'  {s.n}ms QAS reinject Enter(payload={s.p!r})'); s.t.append('ENTER')
            elif k.startswith('C:'): s.c+=k[2:]; print(f'  {s.n}ms Char {k[2:]!r} composer={s.c!r}'); s.gate()
            elif k=='ENTER':
                v=s.c.strip()
                if v: s.c='';s.p=None;s.d=None;s.st=True;s.sent.append(v); print(f'  {s.n}ms SUBMIT {v!r}')
                else: print(f'  {s.n}ms Enter empty = no-op')
                s.gate()
            s.n+=1
s=S(); s.run(['SC','QAS','C:h','C:i'],stall='QAS')
print('  => wiped=',s.wiped,' submitted=',s.sent,' queue=',s.q)
assert s.wiped==['m1 h'] and s.sent==['i'] and s.q==['m1','m2']
print('[ADVISORY] 收割块无条件 clear_input 吞掉用户键入，且过期 Enter 把残片当新消息提交')

